-- Org fence for sapiens module (ADR-0028): entitlement-union policies
-- Generated by metaphor-schema. The session resolver sets
-- `app.scope_unit_ids` (the union of the entitled subtrees);
-- unset or empty sees zero rows. Kind guards reject writes
-- naming a node of any other kind.

-- Migration: org row-level-security fence for sapiens.analytics_metrics
-- Generated by metaphor-schema (ADR-0028). org_unit_id is scoped per request
-- via `set_config('app.scope_unit_ids', <csv>, true)`, the union of the
-- session's entitled subtrees; unset or empty sees zero rows. Shared rows
-- anchor on the root node (always in the union), never on a NULL key.

ALTER TABLE sapiens.analytics_metrics ENABLE ROW LEVEL SECURITY;
ALTER TABLE sapiens.analytics_metrics FORCE  ROW LEVEL SECURITY;
DROP POLICY IF EXISTS analytics_metrics_org_unit_isolation ON sapiens.analytics_metrics;
CREATE POLICY analytics_metrics_org_unit_isolation ON sapiens.analytics_metrics
    FOR ALL
    USING      (org_unit_id = ANY(string_to_array(current_setting('app.scope_unit_ids', true), ',')::uuid[]))
    WITH CHECK (org_unit_id = ANY(string_to_array(current_setting('app.scope_unit_ids', true), ',')::uuid[]));

-- Write-path kind guard (ADR-0028): org_unit_id must name an
-- organization.org_units node of an allowed kind; unknown ids and
-- wrong-kind nodes are rejected at write time.
CREATE OR REPLACE FUNCTION sapiens.analytics_metrics_org_unit_kind_guard() RETURNS trigger AS $$
DECLARE
    v_kind text;
BEGIN
    SELECT kind::text INTO v_kind FROM organization.org_units WHERE id = NEW.org_unit_id;
    IF v_kind IS NULL THEN
        RAISE EXCEPTION 'analytics_metrics.org_unit_id % does not reference an organization.org_units node', NEW.org_unit_id;
    END IF;
    IF v_kind NOT IN ('company', 'branch', 'root') THEN
        RAISE EXCEPTION 'analytics_metrics.org_unit_id must reference a company, branch or root node, got a % node', v_kind;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS analytics_metrics_org_unit_kind_guard ON sapiens.analytics_metrics;
CREATE TRIGGER analytics_metrics_org_unit_kind_guard
    BEFORE INSERT OR UPDATE OF org_unit_id ON sapiens.analytics_metrics
    FOR EACH ROW EXECUTE FUNCTION sapiens.analytics_metrics_org_unit_kind_guard();

